mapper.select:
SELECT id, user_id, token_hash, expires_at, revoked_at, rotated_at, created_at
FROM refresh_tokens
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE refresh_tokens
SET revoked_at = #{now}
WHERE id = #{id} AND revoked_at IS NULL

UPDATE refresh_tokens
SET revoked_at = #{now}, rotated_at = #{now}
WHERE id = #{id} AND revoked_at IS NULL
